  // src/models/task.ts (updated)
  export interface Task { /* ... existing */ parentId?: string; }

  // src/ai.ts
  export async function decomposeGoal(goal: string, apiKey: string, model: string = 'gpt-3.5-turbo'): Promise<string[]> {
    if (!apiKey) return ['Mock subtask 1', 'Mock subtask 2']; // Baseline mock
    const response = await fetch('https://api.openai.com/v1/chat/completions', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${apiKey}` },
      body: JSON.stringify({ model, messages: [{ role: 'user', content: `Break this goal into practical subtasks: ${goal}` }] }),
    });
    const data = await response.json();
    return JSON.parse(data.choices[0].message.content); // Assume response is JSON array
  }

  // src/index.ts (new command)
  commands['decompose-goal'] = async (args) => {
    const opts = minimist(args);
    const description = args[0];
    if (!description) throw new Error('Goal description required');
    const subtasks = await decomposeGoal(description, opts['api-key'] || process.env.TASKFORGE_AI_KEY || '', opts.model);
    const output = { goal: description, subtasks };
    if (opts.persist) {
      const tasks = await loadTasks('tasks.json');
      const parentId = crypto.randomUUID();
      tasks.push({ id: parentId, description, status: 'pending', createdAt: new Date().toISOString(), tags: [], priority: undefined });
      subtasks.forEach(sub => tasks.push({ id: crypto.randomUUID(), description: sub, status: 'pending', createdAt: new Date().toISOString(), parentId, tags: [], priority: undefined }));
      await saveTasks('tasks.json', tasks);
      output.persisted = true;
    }
    console.log(JSON.stringify(output, null, 2));
  };
  ```

